import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.BZAK_utg.js";const g=JSON.parse('{"title":"构建Java云原生镜像：基于SpringBoot的GraalVM镜像","description":"","frontmatter":{"title":"构建Java云原生镜像：基于SpringBoot的GraalVM镜像","date":"2023-12-05","categories":["编程语言","Java"],"tags":["Java","Spring","GraalVM","K8S","Docker"],"prevTitle":"基于PlantUML的Java文本绘图","prevLink":"./基于PlantUML的Java文本绘图.html","nextTitle":"构建Java云原生镜像：基于SpringBoot的分层镜像","nextLink":"./构建Java云原生镜像：基于SpringBoot的分层镜像.html"},"headers":[],"relativePath":"posts/编程语言/构建Java云原生镜像：基于SpringBoot的GraalVM镜像.md","filePath":"posts/编程语言/构建Java云原生镜像：基于SpringBoot的GraalVM镜像.md"}'),l={name:"posts/编程语言/构建Java云原生镜像：基于SpringBoot的GraalVM镜像.md"};function n(p,a,o,r,h,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="构建java云原生镜像-基于springboot的graalvm镜像" tabindex="-1">构建Java云原生镜像：基于SpringBoot的GraalVM镜像 <a class="header-anchor" href="#构建java云原生镜像-基于springboot的graalvm镜像" aria-label="Permalink to &quot;构建Java云原生镜像：基于SpringBoot的GraalVM镜像&quot;">​</a></h1><h2 id="一、引入graalvm组件" tabindex="-1">一、引入graalvm组件 <a class="header-anchor" href="#一、引入graalvm组件" aria-label="Permalink to &quot;一、引入graalvm组件&quot;">​</a></h2><p>在任意<a href="./构建Java云原生镜像：基于SpringBoot的分层镜像.html#一、准备一个springboot项目">SpringBoot项目</a>的基础上，引入以下graalvm的maven插件：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;org.graalvm.buildtools&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;native-maven-plugin&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h2 id="二、使用springboot插件构建镜像" tabindex="-1">二、使用SpringBoot插件构建镜像 <a class="header-anchor" href="#二、使用springboot插件构建镜像" aria-label="Permalink to &quot;二、使用SpringBoot插件构建镜像&quot;">​</a></h2><p><code>spring-boot-maven-plugin</code>插件下的<code>build-image</code>执行目标提供了一键生成镜像的功能，如下所示：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Pnative</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spring-boot:build-image</span></span></code></pre></div><p>执行该命令需要先启动Docker，执行完成后，会自动生成Docker镜像。</p><blockquote><p>在构建镜像的过程中，会自动下载<code>paketobuildpacks/builder-jammy-tiny</code>和<code>paketobuildpacks/run-jammy-tiny</code>这两个辅助镜像。</p></blockquote><blockquote><p>ARM架构的MacBook电脑可能会执行失败，推测是当前（20231209）还没有完成适配，可暂时使用x86机器，或采用<a href="#三使用graalvm插件构建镜像">GraalVM插件</a>完成构建。</p></blockquote><p><code>spring-boot-maven-plugin</code>插件使用Buildpacks完成镜像构建。上述命令中的<code>native</code>配置参数由<code>spring-boot-starter-parent</code>提供，其引入了两个maven执行目标：<code>spring-boot-maven-plugin</code>下的<code>process-aot</code>和<code>native-maven-plugin</code>下的<code>add-reachability-metadata</code>，具体内容可详见<code>spring-boot-starter-parent</code>的pom.xml文件。如果不想引入<code>spring-boot-starter-parent</code>，也可手动配置<code>process-ao</code>和<code>add-reachability-metadata</code>。</p><p>执行完上述命令后，运行容器，并验证应用：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app:1.0-SNAPSHOT</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080</span></span></code></pre></div><h2 id="三、使用graalvm插件构建镜像" tabindex="-1">三、使用GraalVM插件构建镜像 <a class="header-anchor" href="#三、使用graalvm插件构建镜像" aria-label="Permalink to &quot;三、使用GraalVM插件构建镜像&quot;">​</a></h2><p><code>native-maven-plugin</code>插件下的<code>compile</code>执行目标提供了一键生成二进制可执行文件的功能，如下所示：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Pnative</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> native:compile</span></span></code></pre></div><p>执行该命令需要先下载并配置参考GraalVM：首先，在<a href="https://www.graalvm.org/downloads/" target="_blank" rel="noreferrer">GraalVM官方网站</a>下载并安装GraalVM，随后设置JAVA_HOME环境变量。执行完成后，会在target目录下生成二进制可执行文件。</p><blockquote><p>Windwos系统可能需要下载VisualStudio才能执行成功，可使用Linux或Mac操作系统完成构建。</p></blockquote><p>运行可执行文件，并验证应用：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/app</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080</span></span></code></pre></div><p>后续也可将该二进制可执行文件打入Docker镜像，当前暂不支持交叉编译，建议在Linux操作系统下完成构建。</p><blockquote><p>参考文档</p></blockquote><ol><li><a href="https://docs.spring.io/spring-boot/docs/current/reference/html/native-image.html#native-image" target="_blank" rel="noreferrer">SpringBoot GraalVM Native Image Support</a></li><li><a href="https://www.graalvm.org" target="_blank" rel="noreferrer">GraalVM官方网站</a></li></ol>`,25)])])}const k=s(l,[["render",n]]);export{g as __pageData,k as default};
